81: ","hash":"09b62afa881fff99d184e369aef8375b29bee0baeb74f31d2e47c8a46079d1fc","totalLines":81,"nextOffset":null},{"path":"/src/agent-ui/plugins/quick-help-card/index.tsx","content":"1: import { useAgentUILocaleCode } from "@za38.03/agent-ui-plugins";
2: import { useId } from "react";
3: import {
4:   toggleQuickHelpCardExpanded,
5:   useQuickHelpCardExpanded,
6: } from "../../hooks/useQuickHelpCardExpanded";
7: import type { ReactNode } from "react";
8: import "./styles.css";
9: 
10: type QuickHelpCardProps = {
11:   renderSlot?: (name: string, fallback?: ReactNode) => ReactNode;
12: };
13: 
14: const messages: Record<string, { title: string; expand: string; collapse: string }> = {
15:   "zh-CN": { title: "使用帮助", expand: "展开", collapse: "折叠" },
16:   "en-US": { title: "Usage Help", expand: "Expand", collapse: "Collapse" },
17: };
18: 
19: export function QuickHelpCardPlugin(props: QuickHelpCardProps) {
20:   const localeCode = useAgentUILocaleCode();
21:   const text = messages[localeCode] ?? messages["zh-CN"]!;
22:   // Shared with header actions such as the "知道了" action, so both plugins
23:   // control the same expansion state and it survives theme switching.
24:   const expanded = useQuickHelpCardExpanded();
25:   const bodyId = useId();
26: 
27:   const headerActions = props.renderSlot ? props.renderSlot("headerActions", null) : null;
28:   const body = props.renderSlot ? props.renderSlot("body", null) : null;
29: 
30:   return (
31:     <section className="quick-help-card" aria-label={text.title}>
32:       <div className="quick-help-card__header">
33:         <button
34:           type="button"
35:           className="quick-help-card__toggle"
36:           aria-expanded={expanded}
37:           aria-controls={bodyId}
38:           onClick={toggleQuickHelpCardExpanded}
39:         >
40:           <span className="quick-help-card__title">{text.title}</span>
41:           <span className="quick-help-card__indicator" aria-hidden="true">
42:             {expanded ? "▾" : "▸"}
43:           </span>
44:           <span className="quick-help-card__toggle-label">
45:             {expanded ? text.collapse : text.expand}
46:           </span>
47:         </button>
48:         {headerActions ? (
49:           <div className="quick-help-card__header-actions">{headerActions}</div>
50:         ) : null}
51:       </div>
52:       <div className="quick-help-card__body" id={bodyId} hidden={!expanded}>
53:         {body}
54:       </div>
55:     </section>
56:   );
57: }
