2: 
3: /**
4:  * Shared expansion state for the quick help card.
5:  *
6:  * The card itself and the actions placed in its `headerActions` slot are
7:  * separate Plugin instances, so the state lives in one tiny project-owned
8:  * store outside React. Theme switching only re-renders the tree, the module
9:  * (and therefore this state) keeps its value.
10:  */
11: let expanded = true;
12: const listeners = new Set<() => void>();
13: 
14: function subscribe(listener: () => void): () => void {
15:   listeners.add(listener);
16:   return () => {
17:     listeners.delete(listener);
18:   };
19: }
20: 
21: function getSnapshot(): boolean {
22:   return expanded;
23: }
24: 
25: function notify(): void {
26:   for (const listener of listeners) {
27:     listener();
28:   }
29: }
30: 
31: export function setQuickHelpCardExpanded(next: boolean): void {
32:   if (expanded === next) {
33:     return;
34:   }
35:   expanded = next;
36:   notify();
37: }
38: 
39: export function toggleQuickHelpCardExpanded(): void {
40:   setQuickHelpCardExpanded(!expanded);
41: }
42: 
43: /** Collapse the card body, e.g. from a "知道了" header action. */
44: export function collapseQuickHelpCard(): void {
45:   setQuickHelpCardExpanded(false);
46: }
47: 
48: /** Read the current expansion state outside React. */
49: export function getQuickHelpCardExpanded(): boolean {
50:   return expanded;
51: }
52: 
53: /** Subscribe a component to the shared expansion state. */
54: export function useQuickHelpCardExpanded(): boolean {
55:   return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
56: }
