34:           type="button"
35:           className="quick-help-card__toggle"
36:           aria-expanded={expanded}
37:           aria-controls={bodyId}
38:           onClick={toggleQuickHelpCardExpanded}
39:         >
40:           <span className="quick-help-card__title">{text.title}</span>
41:           <span className="quick-help-card__indicator" aria-hidden="true">
42:             {expanded ? "▾" : "▸"}
43:           </span>
